const its = await jira.listItems();
const out = its.map(i => i.gone ? i : ({id:i.id,type:i.issueType,s:i.summary,st:i.status.name,a:i.assignee?.name,p:i.points,d:i.description.slice(0,300),c:i.comments.slice(-3).map(c=>`${c.author} ${c.at}: ${c.body.slice(0,250)}`)}));
const f = await items.read("folder:159d84b7cec4a38c");
return {out, f: f.gone? f : {t:f.title, x:f.text.slice(0,3000)}};

